"""Component L15 MLP down_proj, feature 3009: a "name-field" detector.

It fires on the word "name" when the word labels a field rather than being
ordinary prose: a JSON key (`{"name": ...`), the second half of "first name" or
"given name", and, more weakly, any other "name". It also fires on the `":` that
closes a `"name"` key. Everywhere else it predicts about zero.
The activation is in the component's own units (x·V_c)·‖U_c‖, so the values
below are the typical sizes, not a fitted scale.
"""

READS = ()

NAME_WORDS = {"name", "Name"}
KEY_OPENERS = {'{"', "{'"}
FIRST_WORDS = {"first", "given", "family"}


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    same_doc = len(tokens) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = tokens[-2].strip() if same_doc else ""
    cur = tokens[-1].strip()
    if cur in NAME_WORDS:
        if prev in KEY_OPENERS:
            return carry, 3.3  # {"name": a JSON or config field
        if prev in FIRST_WORDS:
            return carry, 1.9  # first name, given name
        return carry, 0.4  # any other "name"
    if tokens[-1].strip() == '":' and prev == "name":
        return carry, 2.6  # the colon-quote closing a "name" key
    return carry, 0.0

"""Layer-15 MLP hidden unit 3017 (down_proj component 3017), as a readable rule.

Its input direction is mostly that one hidden unit (about 0.83 of its 1.12 norm), so
the component behaves like that unit scaled by its output column. Its activation is
small and noisy (std 0.43), with rare large spikes. The largest positive spikes
mostly sit on a colon or dash that introduces a point right after a setup phrase,
e.g. "the bigger question is [–] how", "one thing you must not do[:] you must",
"the answer to your question is:[ it]". Most of the variance, though, lies on
ordinary content words, which these rules do not capture: the program explains only
a fraction of a percent of the variance.

The program reads only the current token and the few tokens before it in the same
document, and predicts the average activation for the kind of token it is:

- a colon, dash, quote or ellipsis after a setup word (question, problem, answer,
  reason, thing, point, simple, key, ...): a large positive value;
- the same punctuation otherwise: a small positive value;
- commas, "is", "that", "this", "I", "it", "and", "?": a slight positive value;
- "by", "can", "not", "for", "as", "on", digits and closing brackets: a slight negative value;
- anything else: 0.
"""

READS = ()

SETUP_WORDS = {"question", "problem", "answer", "reason", "thing", "point", "concept",
               "simple", "key", "truth", "bit", "idea", "why", "how", "drivers", "sure"}
COLON_LIKE = {":", "–", "—", "“", "…", "...", "：", ";"}
UP_WORDS = {"is", "that", "this", "be", "i", "it", "and", "?", "are", "was", "which"}
DOWN_WORDS = {"by", "can", "not", "for", "as", "on", "from", "with", "at"}
CLOSE_BRACKETS = {")", "]"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip().lower()
    doc = prefix.document_ids
    recent = [s.strip().lower() for s, d in zip(prefix.token_strings[-7:-1], doc[-7:-1])
              if d == doc[-1]]
    if cur in COLON_LIKE:
        value = 1.1 if any(w in SETUP_WORDS for w in recent) else 0.14
    elif cur == ",":
        value = 0.03
    elif cur in UP_WORDS:
        value = 0.06
    elif cur in DOWN_WORDS or cur.isdigit():
        value = -0.05
    elif cur in CLOSE_BRACKETS:
        value = -0.055
    else:
        value = 0.0
    return carry, value

"""Layer 15 MLP down-projection component 3019: a 'label, quote and padding' dip.

What it does: this component is mostly negative. Its activation dips on a few
kinds of token, and sits near zero on ordinary words:
  - a colon that introduces a label ("Note:", "Tests:"): strongly negative,
    most of all in the first few dozen tokens of a document;
  - an opening quotation mark, most of all at the start of a line;
  - a comment or table marker (//, #, |, `);
  - a list bullet, dash or number at the start of a line;
  - a run of padding spaces inside a line (alignment), but not indentation
    at the start of a line, which is about zero;
  - operators (=, -, *, +, <, >), newlines and closing brackets: mildly negative;
  - an opening bracket and digits, and everything else (words, CJK): about zero.

Why: these are the places where a token starts a labelled, quoted or
aligned span rather than running prose. The program keeps only the token's
surface form and whether it sits at a line start or near a document start.
It does not model the large within-class variation (for example which label
a colon follows), so it explains about 15% of the activation variance.

The values are the mean activation of each class on 16k training rows,
rounded. The carry tracks the position within the current document.
"""
import re

READS = ()

COLON = re.compile(r"[ \xa0]?[:：]\s*")
BULLET = re.compile(r"[ \t]*(?:[*\-•+]|\d+[.)]|[#>])[ \t]*")
SPACES = re.compile(r"[ \t\xa0]{2,}")
NEWLINE = re.compile(r"\s*\n\s*")
MARKER = re.compile(r"[ \xa0]?(?://|#|\||`)")
QUOTE = re.compile(r"[ \xa0]?[\"“”'‘’]+")
OPERATOR = re.compile(r"[ \xa0]?[=\-*+<>]+")
DIGITS = re.compile(r"[ \xa0]?\d+")


def step(carry, prefix, upstream):
    # Position within the current document (the row packs several documents).
    doc = prefix.document_ids[-1]
    pos = 0 if carry is None or carry[0] != doc else carry[1] + 1
    s = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    line_start = pos > 0 and "\n" in prev  # this token opens a new line
    if COLON.fullmatch(s):
        v = -6.4 if pos < 16 else -3.7  # label colon
    elif BULLET.fullmatch(s) and line_start:
        v = -2.2  # list bullet or number at a line start
    elif QUOTE.fullmatch(s):
        v = -4.5 if line_start else -2.1  # opening quotation mark
    elif MARKER.fullmatch(s):
        v = -2.3  # comment or table marker
    elif SPACES.fullmatch(s):
        v = -0.3 if line_start else -2.5  # padding inside a line; indentation is ~0
    elif OPERATOR.fullmatch(s):
        v = -1.9 if line_start else -0.7
    elif NEWLINE.fullmatch(s):
        v = -0.7
    elif s.strip() == ")":
        v = -0.6
    elif s.strip() == "(":
        v = 0.3
    elif DIGITS.fullmatch(s):
        v = -0.2
    else:
        v = -0.1  # ordinary words and text
    return (doc, pos), v

"""Layer 15 MLP hidden unit 3020, as read by this down_proj component.

The component reads mostly MLP hidden unit 3020 of layer 15 (about 0.9 of its input
vector's 1.15 norm), with smaller weights spread over many other units. Its activation
is a diffuse, context-driven signal: most of the variance sits in many small values,
and the largest spikes come in a few recognisable places. This program predicts only
those spike groups, each at its mean activation on training text:

  * the shell command word `cd` (an agent starting a bash command, e.g. `cd /workspace`),
    about 9;
  * `OBSERVATION` at the end of a tool-response header (the token `ATION` / `ERV`),
    about 3.5;
  * the first two tokens of a code or command string written into a JSON tool call
    (`"command": "`, `"file_text": "`, `"old_str": "`, `"new_str": "`), about 3.4;
  * a colon right after a word label (`country:`, `Error:`, `name:`), about 0.5.

Everything else is predicted as 0. The carry keeps the last 40 characters of the
document, to see the JSON key and the OBSERVATION header, and a count of how many
tokens remain in a code string's first two tokens.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

CODE_KEYS = ("command", "file_text", "old_str", "new_str")
CD_VALUE = 9.0  # the token `cd`
OBSERVATION_VALUE = 3.5  # `ATION` / `ERV` closing "OBSERVATION"
CODE_START_VALUE = 3.4  # first two tokens of a code/command string value
LABEL_COLON_VALUE = 0.5  # ":" right after a word


def _opens_code_value(text: str) -> bool:
    """Whether `text` ends just inside a JSON string value of a code-carrying key."""
    return any(text.endswith(f'"{key}": "') for key in CODE_KEYS)


def step(carry, prefix, upstream: Mapping):
    tok = prefix.token_strings[-1]
    new_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]
    if carry is None or new_doc:
        carry = {"text": "", "pending": 0}
    before, pending = carry["text"], carry["pending"]

    value = 0.0
    if tok == "cd":
        value = CD_VALUE
    elif tok in ("ATION", "ERV") and "OBSERV" in before[-12:]:
        value = OBSERVATION_VALUE
    elif pending > 0:
        value = CODE_START_VALUE
    elif tok == ":" and len(prefix.token_strings) > 1 and prefix.token_strings[-2].strip().isalpha():
        value = LABEL_COLON_VALUE

    text = (before + tok)[-40:]
    if _opens_code_value(text):
        pending = 2
    else:
        pending = max(pending - 1, 0)
    return {"text": text, "pending": pending}, float(value)

"""Layer 15 MLP unit 3026 (down_proj component 3026), as a word-piece detector.

The component is almost exactly one MLP hidden unit, so its activation is negative on short
pieces of text and positive on long chunks. In plain terms:

- a digit is strongly negative, most of all when the token before it is also a digit;
- object pronouns (them, him, us, it, me, her) and verb particles (up, out, off, down) are
  clearly negative;
- a Chinese character is negative when it follows another Chinese character, and a Chinese
  chunk of three or more characters is positive;
- a single Latin or other letter piece that continues a word (no leading space) is negative;
  a whole word with a leading space is near zero, rising with its length;
- spaces, punctuation and the first token of a document are near zero.

It is a rough description: it explains about 5% of the variance. The activation also depends
on which specific token it is and on context, which these classes do not capture.
"""

import regex

READS = ()

DIGIT = regex.compile(r"\d+")
HAN = regex.compile(r"\p{Han}+")
LETTERS = regex.compile(r"\p{L}+")
SYMBOLS = regex.compile(r"[\p{P}\p{S}]+")
PRONOUNS = {"them", "him", "us", "it", "me", "her"}
PARTICLES = {"up", "out", "off", "down"}


def step(carry, prefix, upstream):
    # The first token of a document has no earlier token to continue, so it is zero.
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, 0.0
    cur, prev = prefix.token_strings[-1], prefix.token_strings[-2]
    word, before = cur.strip(), prev.strip()
    n = len(word)
    if word.lower() in PRONOUNS:
        value = -1.8
    elif word.lower() in PARTICLES:
        value = -1.5
    elif not word or SYMBOLS.fullmatch(word):
        value = 0.1
    elif DIGIT.fullmatch(word):
        value = -1.0 if DIGIT.fullmatch(before) else -0.6
    elif HAN.fullmatch(word):
        if n == 1:
            value = -1.0 if HAN.fullmatch(before) else -0.3
        else:
            value = 0.5 * (n - 2)
    elif LETTERS.fullmatch(word):
        # longer pieces are higher; a piece with no leading space is lower still
        value = 0.12 * min(n, 8) - 0.5
        if not cur[0].isspace():
            value -= 0.3
    else:
        value = 0.0
    return carry, value

"""Layer 15 MLP neuron 3035 (down_proj component 3035), read as a comparison-clause detector.

What the component is: its read vector is mostly the MLP hidden unit 3035 of layer 15
(about 80% of its norm), so its activation tracks that one neuron's value.
Most of its activation is small and diffuse. Its strong negative tail sits on comparisons:
"is better THAN most people", "more ... THAN the", "as fast AS most", "not EVEN",
and on the word that opens the standard of comparison right after "than"
("than the", "than most", "than any").
"than" after "rather", "other" or "different" is a choice, not a comparison of degree,
and stays at zero.

This program writes those rules down as word-level values. It is a sketch: it covers the
readable part of the activation and leaves out the diffuse rest, which no word rule captures.
"""

READS = ()

# Comparatives that make a following "than" a comparison of degree.
COMPARATIVE_WORDS = {"more", "less", "fewer", "better", "worse", "greater", "lower", "higher"}
# "rather than", "other than", "different than": a choice, not a comparison of degree.
CHOICE_WORDS = {"rather", "other", "different"}
# Words that, before "even", make it the scalar "not even" / "or even" kind.
NEGATION_OR_CONJUNCTION = {"not", "or", ",", "but", "that", "so", "never", "nor"}
# Degree words before "as", as in "as much as", "as high as", "twice as fast as".
DEGREE_WORDS = {"much", "so", "high", "low", "fast", "good", "large", "many", "far", "twice", "half"}
# Words that open the standard of comparison after "than" ("than most", "than any").
STANDARD_WORDS = {"most", "any", "some", "all", "anyone", "anything", "every"}


def value_now(prev, word):
    """Activation at `word`, given the word just before it in the same document."""
    if word == "than":
        if prev in CHOICE_WORDS:
            return 0.0
        if prev.endswith("er") or prev in COMPARATIVE_WORDS:
            return -2.5
        return -1.0
    if word == "as" and prev in DEGREE_WORDS:
        return -1.5
    if word == "even":
        return -1.5 if prev in NEGATION_OR_CONJUNCTION else 0.0
    if prev == "than":
        return -3.0 if word in STANDARD_WORDS else -0.6
    return 0.0


def step(carry, prefix, upstream):
    # The previous word counts only inside the same document; the newest token is the word.
    word = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    return carry, float(value_now(prev, word))


def main_demo():
    """Print the value at each word of a sentence, to read the rules at work."""
    sentence = "It is far better than most people, and rather than wait, it is even faster as well."
    prev = ""
    for w in sentence.replace(",", " ,").replace(".", " .").split():
        word = w.lower()
        print(f"{w:>10}  {value_now(prev, word):+.1f}")
        prev = word


if __name__ == "__main__":
    main_demo()

"""Heading and label closers: a weak component that is mostly negative at labels.

The component writes into the residual stream, and its activation is mostly near zero
with occasional large values. Its most negative values come at the token that closes a
short label or heading, the colon (or line break) just before the label's body text:

    1. **Physical Health:**   -> strongly negative on the colon
    Chain of Thought:         -> negative on the colon
    Mercury sesquiquadrate    -> mildly negative on the line break

Everything else is predicted as a small constant (0). The values are group means over
training text, so this is a coarse description of the component, not the whole of it.
"""

READS = ()

LIST_START = ("1.", "2.", "3.", "4.", "5.", "6.", "7.", "8.", "9.", "-", "*", "•", "#")


def line_before(prefix, limit=40):
    """Text of the current line before the newest token, within the same document."""
    parts = []
    doc = prefix.document_ids[-1]
    start = max(-1, len(prefix.token_strings) - 2 - limit)
    for i in range(len(prefix.token_strings) - 2, start, -1):
        if prefix.document_ids[i] != doc:
            break
        s = prefix.token_strings[i]
        if "\n" in s:
            parts.append(s.split("\n")[-1])
            break
        parts.append(s)
    return "".join(reversed(parts))


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    line = line_before(prefix)
    words = len(line.split())
    value = 0.0
    if tok.strip().rstrip("\n") in (":", "："):
        if line.lstrip().startswith(LIST_START):
            value = -1.05  # colon closing a numbered or bulleted item's label
        elif words <= 3:
            value = -0.57  # colon closing a short label
        else:
            value = -0.34  # colon after a longer line
    elif "\n" in tok:
        if 1 <= words <= 6 and not line.rstrip().endswith((".", "!", "?", ",", "。")):
            value = -0.14  # line break after a short title
        elif words >= 12:
            value = 0.09
    elif tok.strip() == "." and 1 <= words <= 3:
        value = -0.30  # period closing a short label
    return carry, value

"""Predicted activation of one MLP output component in layer 15 (down_proj:3057).

The component is near 0 on most tokens (typical values within about +-0.5) and has rare,
strong negative dips. This program predicts the dips it can name from the text so far:
  - "return", "exit", "continue", "break", "goto", "die": code leaving a block early;
  - "me" or "'s" right after "let" ("Let me", "Let's"): the model announcing its next step;
  - sentence connectives "so", "but", "therefore", "thus", "hence", "however", ...: a
    conclusion or contrast being introduced.
Each is a fixed value. Weaker dips on "we", "I", "will", "can", "need" (planning talk).
Every other token predicts 0.

It explains only about 2% of the variance: most of the component's variance sits on common
tokens in contexts this program does not model.
"""

READS = ()

EXIT_WORDS = {"return", "exit", "continue", "break", "goto", "die"}
CONNECTIVES = {"so", "but", "therefore", "thus", "hence", "however", "anyway", "consequently"}
PLAN_WORDS = {"we", "i", "will", "can", "need"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    before = ""
    if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        before = prefix.token_strings[-2].strip().lower()
    if word in EXIT_WORDS:
        return carry, -1.0
    if word in ("me", "'s") and before == "let":
        return carry, -1.8
    if word in CONNECTIVES:
        return carry, -0.7
    if word in PLAN_WORDS:
        return carry, -0.15
    return carry, 0.0

"""Relative-clause and modifier openers, scaled by depth into a sentence.

The component is positive on words that open a phrase modifying what came before
inside a sentence: relative pronouns (which, that, who, where, ...) most of all, then
prepositions and subordinators (to, of, in, for, with, as, than, ...). Determiners,
copulas and commas are slightly negative early in a sentence and slightly positive
later. Everything else is near zero. Each word's value moves from its value at the
start of a sentence to its value 30 tokens in, so the same word counts for more deep
inside a long sentence.
"""

READS = ()

RELATIVE = {"which", "that", "who", "whom", "whose", "where", "when",
            "qui", "que", "dont", "cui", "welche", "welcher", "которые", "который", "которая", "которое", "где"}
PREPOSITION = {"to", "of", "in", "for", "with", "by", "on", "at", "from", "as", "than", "after",
               "into", "about", "like", "over", "under", "through", "during", "between", "without",
               "within", "upon", "against", "among", "since", "until", "despite", "including", "such", "if"}
FUNCTION = {"the", "a", "an", "is", "was", "are", "were", "be", "been", ","}
SENTENCE_END = {".", "!", "?", "\n", "\n\n"}

# value at the start of a sentence, and 30 tokens into it
START = {"relative": 0.4, "preposition": 0.0, "function": -0.4}
DEEP = {"relative": 2.9, "preposition": 1.1, "function": 0.3}
RAMP = 30


def _kind(word):
    if word in RELATIVE:
        return "relative"
    if word in PREPOSITION:
        return "preposition"
    if word in FUNCTION:
        return "function"
    return None


def step(carry, prefix, upstream):
    # carry: (tokens since the last sentence end, document label of the last token)
    since, doc = carry if carry is not None else (0, None)
    word = prefix.token_strings[-1].strip().lower()
    if prefix.document_ids[-1] != doc:
        since = 0
    kind = _kind(word)
    value = 0.0
    if kind is not None:
        depth = min(since, RAMP) / RAMP
        value = START[kind] + (DEEP[kind] - START[kind]) * depth
        if kind == "relative" and len(prefix.token_strings) > 1 and prefix.token_strings[-2].strip() == ",":
            value *= 1.7
    since = 0 if word in SENTENCE_END else since + 1
    return (since, prefix.document_ids[-1]), value
